mapper.select:
SELECT b.seckill_id AS activityId, b.seckill_name AS activityName, DATE_FORMAT( b.seckill_start_time, "%Y-%m-%d %H:%i:%s" ) AS startTime, DATE_FORMAT( b.seckill_end_time, "%Y-%m-%d %H:%i:%s" ) AS endTime, sb.shop_name AS shopName, '正常' AS stateLabel, b.seckill_state AS seckillState, b.seckill_hour AS seckillHour, DATE_FORMAT( b.seckill_create_time, "%Y-%m-%d %H:%i:%s" ) AS seckillCreateTime FROM ${database.prefix.activity}hou_addon_activity_seckill_base b LEFT JOIN ${database.prefix.business}hou_shop_base sb ON b.shop_id = sb.supplier_shop_id
and sb.shop_name like CONCAT('%',#{param.shopName},'%')
and b.shop_id = #{param.shopId}
and b.seckill_name like CONCAT('%',#{param.seckillName},'%')
and b.seckill_state = #{param.seckillState}
order by b.seckill_create_time desc

select seckill_id, seckill_name, seckill_start_time, seckill_end_time, user_id, shop_id, user_nick_name, shop_name, seckill_state, seckill_hour from ${database.prefix.activity}hou_addon_activity_seckill_base where shop_id = #{param.shopId}
and seckill_name like concat('%', #{param.seckillName} ,'%')
and seckill_state = #{param.seckillState}
order by seckill_create_time desc
